'use strict';
const pmCardHistory=new Map(),pmCardPending=new Set(),pmCardQueue=[];let pmCardObserver,pmCardActive=0;
function pmSplit(yes,no){return Number.isFinite(yes)&&Number.isFinite(no)&&yes>=0&&no>=0&&yes<=1&&no<=1&&yes+no>0?100*yes/(yes+no):null}
function pmCompactDollars(n){return Number.isFinite(n)?'$'+new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(n):'—'}
function predictionCard(m){
 const yes=m.outcomes.find(o=>o.label==='Yes')?.price,no=m.outcomes.find(o=>o.label==='No')?.price,split=pmSplit(yes,no),scaled=split!==null&&Math.abs(yes+no-1)>.005;
 const move=Number.isFinite(m.change)?`${m.change>0?'↑':m.change<0?'↓':'→'} ${(Math.abs(m.change)*100).toFixed(1)} pp`:'—';
 return `<button class="pm-market ${pmSelected?.id===m.id?'selected':''}" data-pm-market="${esc(m.id)}"><span class="pm-market-title">${esc(m.question)}</span>${m.insight?'<span class="pm-card-badge">poor insight</span>':''}<span class="pm-outcome-row"><span class="pm-yes">Yes <b>${pmCents(yes)}</b><small>${pmPercent(yes)} implied</small></span><span class="pm-no">No <b>${pmCents(no)}</b><small>${pmPercent(no)} implied</small></span></span><span class="pm-odds-bar" role="img" aria-label="${split===null?'Price split unavailable':`Yes ${pmPercent(yes)}, No ${pmPercent(no)}${scaled?'; bar proportional to the two prices':''}`}" title="${scaled?'Bar proportional to quoted prices; prices do not sum to $1':'Green: Yes · red: No'}">${split===null?'<span class="pm-bar-unknown"></span>':`<span class="pm-bar-yes" style="width:${split.toFixed(4)}%"></span><span class="pm-bar-no" style="width:${(100-split).toFixed(4)}%"></span><i class="pm-midpoint"></i>`}</span>${scaled?'<small class="pm-scaled">Bar scaled to quoted prices</small>':''}<span class="pm-card-trend"><span class="pm-card-move ${m.change<0?'loss':m.change>0?'gain':''}"><b>${move}</b><small>Yes · 24h change</small></span><span class="pm-card-chart" data-pm-history="${esc(m.id)}">${pmCardChart(pmCardHistory.get(m.id))}</span></span><span class="pm-card-stats"><span>24h volume<b>${pmCompactDollars(m.volume)}</b></span><span>Liquidity<b>${pmCompactDollars(m.liquidity)}</b></span><span>Ends<b>${m.end?date(m.end):'Unknown'}</b></span></span><span class="pm-card-foot">${m.insight?'Sourced assessment':m.connections?.length?m.connections.length+' related briefs':'No current assessment'}<span>Rules & order book ↗</span></span></button>`;
}
function pmCardChart(entry){
 if(!entry)return '<small>7d Yes price · loading…</small>';
 const points=(entry.data?.value?.points||[]).filter(p=>Number.isFinite(p.t)&&Number.isFinite(p.p)&&p.p>=0&&p.p<=1),first=points[0],last=points.at(-1);
 if(points.length<2||last.t<=first.t)return '<small>7d history unavailable</small>';
 const coords=points.map(p=>`${(3+(p.t-first.t)/(last.t-first.t)*174).toFixed(1)},${(43-p.p*38).toFixed(1)}`).join(' ');
 return `<svg viewBox="0 0 180 48" role="img" aria-label="Seven-day Yes price, ${pmPercent(first.p)} to ${pmPercent(last.p)}; fixed zero to one hundred percent scale"><line x1="3" x2="177" y1="24" y2="24" stroke="#dce5df" stroke-dasharray="2 3"/><polyline points="${coords}" fill="none" stroke="${last.p<first.p?'#b65359':'#24846b'}" stroke-width="2" stroke-linejoin="round"/></svg><small>Yes · 7d · 0–100%${entry.data?.stale?' · stale':''}</small>`;
}
function observePredictionCards(){
 pmCardObserver?.disconnect();const root=document.querySelector('#pmMarkets');if(!root)return;
 pmCardObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){const id=e.target.dataset.pmHistory,old=pmCardHistory.get(id);if((!old||Date.now()-old.at>(old.data?.value?600000:60000))&&!pmCardPending.has(id)){pmCardPending.add(id);pmCardQueue.push(id)}pmCardObserver.unobserve(e.target)}drainPredictionCards()},{root,rootMargin:'100px'});
 root.querySelectorAll('[data-pm-history]').forEach(el=>pmCardObserver.observe(el));
}
function drainPredictionCards(){while(pmCardActive<3&&pmCardQueue.length){const id=pmCardQueue.shift();if(view!=='predictions'||!document.querySelector(`[data-pm-history="${id}"]`)){pmCardPending.delete(id);continue}pmCardActive++;(async()=>{try{const r=await fetch('/api/predictions/history?id='+id,{signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error();pmCardHistory.set(id,{at:Date.now(),data:await r.json()})}catch{pmCardHistory.set(id,{at:Date.now(),data:null})}finally{document.querySelectorAll(`[data-pm-history="${id}"]`).forEach(el=>el.innerHTML=pmCardChart(pmCardHistory.get(id)));pmCardActive--;pmCardPending.delete(id);drainPredictionCards()}})()}}
